import type { AppId, LauncherApp } from '../../common/catalog';

/**
 * Each app's logo — the midnite moon in the app's accent with its glyph over
 * it, generated by `scripts/generate-app-logos.cjs` (`moon run launcher:logos`)
 * from Studio's own icon. Regenerate after changing an accent or a glyph.
 */
const LOGOS = import.meta.glob<string>('../assets/app-logos/*.png', { eager: true, import: 'default' });

export function logoUrl(id: AppId): string | undefined {
  return LOGOS[`../assets/app-logos/${id}.png`];
}

export function AppIcon({ app, size = 64 }: { app: LauncherApp; size?: number }) {
  return (
    <img
      className="app-icon"
      src={logoUrl(app.id)}
      width={size}
      height={size}
      alt=""
      draggable={false}
      style={{ ['--accent' as string]: app.accent }}
    />
  );
}
